"""Build mt5/Saad_drl.mq5 = Saad_regime + DRL position sizing (Zee 2026-10-13, PPO / Kelly log-wealth).
At each entry the EA computes the observation [ER14, ATR14/ATR200, realized vol 14, distance to the 50 EMA
(trade way +, in ATRs), side] and
  * InpDrlLog    - logs it (+ position id) to Common\\Files\\saad_drl_<InpMetaTag>.csv; with InpMetaLog the
                   trade's final net goes to saad_meta_<tag>_out.csv. drl_train.py trains only on these.
  * InpDrlMode=1 - the trained PPO policy network (SaadDrlPolicy.mqh, generated by drl_train.py) gives a
                   lot multiplier 0..2 (Zee: up to 2 lots is fine); lots = InpLots x multiplier; < 0.1 = skip.
  * InpDrlMode=2 - constant multiplier InpDrlConst (the fair benchmark: same average size, no timing)."""
src = r'C:\Users\zeesh\turtle\mt5\Saad_regime.mq5'
dst = r'C:\Users\zeesh\turtle\mt5\Saad_drl.mq5'
s = open(src, encoding='utf-8').read()


def rep(a, b):
    global s
    assert s.count(a) == 1, (s.count(a), a[:80])
    s = s.replace(a, b)


rep('#include "SaadRegimeModel.mqh"', '#include "SaadRegimeModel.mqh"\n#include "SaadDrlPolicy.mqh"')
rep("input int    InpRegimeMode  = 0;",
    """input int    InpDrlMode     = 0;      // InpDrlMode — DRL sizing: 0 off · 1 PPO policy compiled into the EA · 2 constant InpDrlConst (benchmark)
input double InpDrlConst    = 1.0;    // InpDrlConst — mode 2: lot multiplier for every trade
input double InpDrlMaxMult  = 2.0;    // InpDrlMaxMult — never more than this x InpLots (Zee: up to 2 lots)
input bool   InpDrlLog      = false;  // InpDrlLog — log every entry's DRL observation (training data)
input int    InpRegimeMode  = 0;""")
rep("int g_metaVeto = 0;", "int g_metaVeto = 0;\nint g_drlVeto = 0; double g_drlSum = 0; int g_drlN = 0;")

rep("void DoEntry(int side, double sl)\n{", r'''//--- DRL sizing --------------------------------------------------------------
bool DrlObs(int side, double &o[])
{
   double x[];
   if (!RegFeatures(x)) return false;
   double atr = Buf(hAtr, 1); if (atr <= 0) return false;
   ArrayResize(o, DRL_NOBS);
   o[0] = x[0]; o[1] = x[1]; o[2] = x[2];
   o[3] = side * (iClose(_Symbol, PERIOD_CURRENT, 1) - Ema(50, 1)) / atr;
   o[4] = side;
   return true;
}
double DrlMult(int side, double &o[])
{
   if (InpDrlMode == 2) return MathMin(InpDrlConst, InpDrlMaxMult);
   if (!DrlObs(side, o)) return 1.0;
   return MathMax(0.0, MathMin(InpDrlMaxMult, DrlPolicy(o)));
}

void DoEntry(int side, double sl)
{''')
rep("   double lots = LotsFor(side, en, sl);\n   if (lots <= 0) { DSkip(side, \"even the minimum lot risks too much of this account\"); return; }",
    """   double lots = LotsFor(side, en, sl);
   if (lots <= 0) { DSkip(side, "even the minimum lot risks too much of this account"); return; }
   double dobs[]; double dmult = -1;
   if (InpDrlLog) DrlObs(side, dobs);
   if (InpDrlMode > 0) {
      dmult = DrlMult(side, dobs);
      if (dmult < 0.1) {
         g_drlVeto++; g_filtered++;
         DSkip(side, StringFormat("DRL size %.2f < 0.1", dmult));
         return;
      }
      double step = SymbolInfoDouble(_Symbol, SYMBOL_VOLUME_STEP), mn = SymbolInfoDouble(_Symbol, SYMBOL_VOLUME_MIN);
      lots = MathMax(mn, MathRound(lots * dmult / step) * step);
      lots = NormalizeDouble(lots, 2);
      g_drlSum += dmult; g_drlN++;
   }""")
rep("   if (InpMetaLog) MetaAppend(\"feat\", MetaHeader(), MetaRow(t, side, mf, mprob, 0));\n",
    """   if (InpMetaLog) MetaAppend("feat", MetaHeader(), MetaRow(t, side, mf, mprob, 0));
   if (InpDrlLog && ArraySize(dobs) == DRL_NOBS) {
      string fn = StringFormat("saad_drl_%d", InpMetaTag);
      string row = StringFormat("%I64u,%s", t, TimeToString(TimeCurrent(), TIME_DATE | TIME_SECONDS));
      for (int k = 0; k < DRL_NOBS; k++) row += StringFormat(",%.10f", dobs[k]);
      int h = FileOpen(fn + ".csv", FILE_READ | FILE_WRITE | FILE_TXT | FILE_COMMON | FILE_SHARE_READ | FILE_ANSI);
      if (h != INVALID_HANDLE) {
         if (FileSize(h) == 0) FileWriteString(h, "pos_id,time,o_er,o_atr_ratio,o_rvol,o_ema50_dist,o_side,mult,lots\\r\\n");
         FileSeek(h, 0, SEEK_END); FileWriteString(h, row + StringFormat(",%.6f,%.2f\\r\\n", dmult, lots)); FileClose(h);
      }
   }
""")
rep("   hAtr200 = iATR(_Symbol, PERIOD_CURRENT, 200);\n",
    "   hAtr200 = iATR(_Symbol, PERIOD_CURRENT, 200);\n   if (InpDrlLog && MQLInfoInteger(MQL_TESTER)) FileDelete(StringFormat(\"saad_drl_%d.csv\", InpMetaTag), FILE_COMMON);\n")
rep('   PrintFormat("[SAAD-META] vetoed %d trades',
    '   PrintFormat("[SAAD-DRL] mode %d: %d trades sized, average multiplier %.3f, %d skipped (< 0.1)", InpDrlMode, g_drlN, g_drlN > 0 ? g_drlSum / g_drlN : 0, g_drlVeto);\n'
    '   PrintFormat("[SAAD-META] vetoed %d trades')
open(dst, 'w', encoding='utf-8').write(s)
print('wrote', dst)
